protected boolean inititalizeRebateTransaction(TAMRebateTrans _rebateTrans, TAMRebateJournalTrans _rebateJournalTrans, TAMRebateDatePeriod _rebateDatePeriod)
{
    TAMRebateTrans  rebateTrans;
    TAMRebateDeal   rebateDeal;
    TAMRebateDateTrans  rebateDateTrans;
    TAMRebateTable  rebateTable;
    METTierRateTrans    tierRateTrans;
    METTierRebateTrans  tierRebateTrans;

    boolean ret = next inititalizeRebateTransaction(_rebateTrans, _rebateJournalTrans, _rebateDatePeriod);

    select firstonly rebateTable
        where rebateTable.RebateId == _rebateTrans.RebateId;

    select firstonly rebateDeal
        where rebateDeal.RecId == rebateTable.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        select firstonly tierRateTrans
        where tierRateTrans.RebateId == _rebateTrans.RebateId
        && tierRateTrans.FromDate <= _rebateTrans.RebateRefDate
        && tierRateTrans.ToDate >= _rebateTrans.RebateRefDate
            && tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Provision;
        //&& (tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate ||
          //  tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Provision);

        if (tierRateTrans.RecId)
        {
            _rebateTrans.RebateAmount = (_rebateTrans.RebateRefAmount * tierRateTrans.EligibleRebate)/100;
        }
    }
    /*(else if (rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Provision
               && rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        select firstonly tierRateTrans
        where tierRateTrans.RebateId == _rebateTrans.RebateId
        && tierRateTrans.FromDate <= _rebateTrans.RebateRefDate
        && tierRateTrans.ToDate >= _rebateTrans.RebateRefDate
        && tierRateTrans.RebateTransactionType == TAMRebateTransactionType::Provision;

        _rebateTrans.RebateAmount = (_rebateTrans.RebateRefAmount * tierRateTrans.EligibleRebate)/100;
    }*/

    return ret;
}
